#!/usr/bin/env -S uv run --script
# Synced from bootstrap: repo/tools/dprint/tasks/code-format-dprint.py. Do not edit this file.
# The next sync writes it again, and each change in this file is lost.
# /// script
# requires-python = ">=3.14"
# dependencies = []
# ///
# MISE description="Check or format the files with dprint"
# MISE hide=true
# MISE tools={uv="latest", python="3.14"}

# USAGE flag "--all" help="format every file of the repository"
# USAGE flag "--debug" help="emit debug logs"
# USAGE flag "--fix" help="apply fixes"
# USAGE arg "[files]" var=#true help="the files to format; the default is the uncommitted files"

import os
import sys

sys.dont_write_bytecode = True
sys.path.insert(0, f"{os.environ['MISE_PROJECT_ROOT']}/.config/mise/tasks/_scripts")
import helpers  # noqa: E402


def flag(name):
  """Whether the # USAGE flag name is set."""
  return os.environ.get(f"usage_{name}", "false") == "true"


def main():
  # Shipped with the dprint tool. Without dprint, the task does not apply and
  # prints nothing.
  if not helpers.has_tool("dprint"):
    return 0
  os.chdir(os.environ["MISE_PROJECT_ROOT"])

  log_level = "debug" if flag("debug") else "warn"
  cmd = "fmt" if flag("fix") else "check"

  # The list of gate_files (no # FILES header: every file of the set). dprint
  # picks the files of its plugins. With no file, the gate does not apply and
  # prints nothing.
  args = [f"--{name}" for name in ("all", "debug", "fix") if flag(name)]
  file_list = helpers.gate_files(__file__, *args, *helpers.usage_files())
  try:
    if os.path.getsize(file_list) == 0:
      return 0

    helpers.print_header("Formatting the files with dprint ...")
    with open(file_list, "rb") as stdin:
      result = helpers.tool("dprint", cmd, "--allow-no-files", "--log-level", log_level, "--stdin-files", stdin=stdin)
    return result.returncode
  finally:
    os.remove(file_list)


if __name__ == "__main__":
  sys.exit(main())
